// Ponte segura: valida o pedido da interface e monta o corpo para o LiveAvatar.
// A chave de API NUNCA passa por aqui: fica na credencial do nó HTTP Request.
const CODIGO_APRESENTACAO = 'G29-DEFINIR-NO-N8N'; // troque no editor do n8n; sessões reais (com créditos) exigem este código
const WAYNE_SANDBOX = 'dd73ea75-1218-4ef3-92ce-606d5f7fbc0a'; // único avatar do modo sandbox (gratuito, ~1 min)
const AVATAR_PADRAO = '65f9e3c9-d48b-4118-b73a-4ae2e3cbb8f0'; // avatar público de exemplo da documentação; pode ser trocado
const body = ($input.first().json.body) || {};
const sandbox = body.is_sandbox !== false; // padrão: sandbox (não consome créditos)
if (!sandbox && String(body.codigo_apresentacao || '') !== CODIGO_APRESENTACAO) {
  return [{ json: { ok: false, erro: 'Código de apresentação inválido: sessão real (com créditos) não autorizada.' } }];
}
const dur = Math.min(Math.max(parseInt(body.max_session_duration || (sandbox ? 60 : 120), 10) || 60, 30), 600);
const tokenBody = {
  mode: 'FULL',
  avatar_id: sandbox ? WAYNE_SANDBOX : (String(body.avatar_id || '').trim() || AVATAR_PADRAO),
  is_sandbox: sandbox,
  max_session_duration: dur,
  avatar_persona: { language: String(body.language || 'pt') },
};
return [{ json: { ok: true, is_sandbox: sandbox, tokenBody } }];

const j = $input.first().json;
const d = j.data || {};
if (d.session_token) {
  return [{ json: { ok: true, session_id: d.session_id, session_token: d.session_token, is_sandbox: $('Validar pedido').first().json.is_sandbox, max_session_duration: $('Validar pedido').first().json.tokenBody.max_session_duration } }];
}
return [{ json: { ok: false, erro: 'LiveAvatar recusou o pedido de token.', detalhe: j.message || j.detail || j.error || JSON.stringify(j).slice(0, 300), code: j.code } }];
